// chacha20: the ChaCha20 stream cipher of RFC 8439 (key bytes 0-31, nonce
// 000000090000004a00000000, counter from 1) over 8 MiB of generated bytes.
// Prints a position-weighted checksum of the encrypted bytes, and the
// first 16 of them in hexadecimal.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ROTL(x, r) ((x) << (r) | (x) >> (32 - (r)))
#define QR(a, b, c, d) (s[a] += s[b], s[d] ^= s[a], s[d] = ROTL(s[d], 16), s[c] += s[d], s[b] ^= s[c], s[b] = ROTL(s[b], 12), \
                        s[a] += s[b], s[d] ^= s[a], s[d] = ROTL(s[d], 8), s[c] += s[d], s[b] ^= s[c], s[b] = ROTL(s[b], 7))

static void block(const uint32_t *key, const uint32_t *nonce, uint32_t counter, uint8_t *out) {
    uint32_t init[16] = {0x61707865, 0x3320646E, 0x79622D32, 0x6B206574}, s[16];
    memcpy(init + 4, key, 32);
    init[12] = counter;
    memcpy(init + 13, nonce, 12);
    memcpy(s, init, sizeof s);
    for (int r = 0; r < 10; r++) {
        QR(0, 4, 8, 12); QR(1, 5, 9, 13); QR(2, 6, 10, 14); QR(3, 7, 11, 15);
        QR(0, 5, 10, 15); QR(1, 6, 11, 12); QR(2, 7, 8, 13); QR(3, 4, 9, 14);
    }
    for (int i = 0; i < 16; i++) {
        uint32_t w = s[i] + init[i];
        for (int j = 0; j < 4; j++) out[4 * i + j] = (uint8_t)(w >> (8 * j));
    }
}

int main(void) {
    int64_t n = 1 << 23;
    uint8_t kb[32], nb[12] = {0, 0, 0, 9, 0, 0, 0, 0x4a, 0, 0, 0, 0}, ks[64];
    for (int i = 0; i < 32; i++) kb[i] = (uint8_t)i;
    uint32_t key[8], nonce[3];
    memcpy(key, kb, 32);
    memcpy(nonce, nb, 12);
    uint8_t *out = malloc(n);
    for (int64_t b = 0; b < n / 64; b++) {
        block(key, nonce, (uint32_t)(1 + b), ks);
        for (int j = 0; j < 64; j++) {
            int64_t i = 64 * b + j;
            out[i] = (uint8_t)((i * 2654435761) >> 13 & 255) ^ ks[j];
        }
    }
    int64_t check = 0;
    for (int64_t i = 0; i < n; i++) check += out[i] * (i % 251 + 1);
    printf("%lld ", (long long)check);
    for (int i = 0; i < 16; i++) printf("%02x", out[i]);
    printf("\n");
    return 0;
}
